import json,hashlib,subprocess
from pathlib import Path
p=Path('bench/x176/receipts')
def read(name):return json.loads((p/name).read_text())
screen=read('screen.json');gate=read('gate.json');ind=read('independent.json');runtime=read('runtime-summary.json');frontier=read('frontier-compare.json')['summary']
assert len(gate['rows'])==6 and ind['paidExact']==6 and ind['strofosTournamentExact']==7 and not ind['unsupported']
assert frontier['lanes']==29 and frontier['sourceReadEqual']==29
assert read('frontier-provenance.json')['sha256']==hashlib.sha256((p/'frontier.jsonl').read_bytes()).hexdigest()
assert read('count-A.json')==read('count-B.json') and read('vector-A.json')==read('vector-B.json')
runs=read('runtime.json');assert len(runs)==24 and all(r['exit']==0 for r in runs)
for lane in set(r['path'] for r in runs):assert len({r['hash'] for r in runs if r['path']==lane})==1
rawWins=[{'path':r['path'],'raw':r['raw'],'best':min(p['tokens'] for p in r['plans'])} for r in screen['rows'] if r.get('plans') and any(p['tokens']<r['raw'] for p in r['plans'])]
result=dict(accepted=False,reason='No broad paid-parent gains; native NOT_RUN; significant speed gate failed',newCodec='KYKLOGRAF',unit=screen['checks'],attacks=read('attacks.json')['checks'],independent=ind,paid=gate,rawWins=rawWins,frontier=frontier,speed=runtime,native='NOT_RUN',kernels='NOT_RUN',productionChanged=False)
assert not runtime['accepted'] and all(r['selected']==r['base'] for r in gate['rows'])
(p/'summary.json').write_text(json.dumps(result,indent=2))
files=[Path('src/lib/omega/kyklograf.ts'),Path('src/lib/omega/strofos.ts'),Path('src/lib/omega/bpe-fast.ts'),Path('src/lib/omega/bpe.ts')]+list(Path('bench/x176').glob('*.ts'))+list(Path('bench/x176').glob('*.py'))+list(Path('bench/x176').glob('*.sh'))+list(Path('bench/x176').glob('*-build.mjs'))
files+=list(p.glob('*.json'))
files=[f for f in files if f.name!='validation.json']
(p/'validation.json').write_text(json.dumps(dict(scope='Current-source gates and compiler/build passed; long paid/timing/replay receipts checked, not regenerated by validate.sh; hashes bind these artifacts, not a theorem proof',sha256={str(f):hashlib.sha256(f.read_bytes()).hexdigest() for f in sorted(set(files))},versions={cmd:subprocess.check_output(cmd.split(),text=True).strip() for cmd in ['node --version','npm --version','python3 --version']}),indent=2))
print(json.dumps({k:v for k,v in result.items() if k in ['accepted','unit','attacks','frontier','speed','rawWins']},indent=2))
